#!/usr/bin/env python3
"""Spring quarter shipped-orders reconciliation (read-only against the local order service).

Every successful response is cached under DATA, so a stopped run resumes without
refetching, and the result can be recomputed offline.
"""
import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request
from collections import Counter
from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal

BASE = "http://localhost:8080"
WORK = "/tmp/shipped-recon"
DATA = os.path.join(WORK, "data")
LOG = os.path.join(WORK, "run.log")
RESULT = "/workspace/result.json"

# Half-open window in UTC: 1 Mar 2025 00:00:00 up to, but not including, 1 Jun 2025 00:00:00.
WINDOW_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
WINDOW_END = datetime(2025, 6, 1, tzinfo=timezone.utc)
REGIONS = ("north", "south", "east", "west")
MAX_TRANSIENT = 12  # failed tries allowed for one request before the run stops

stats = Counter()


def log(msg):
    line = "%s %s" % (datetime.now(timezone.utc).strftime("%H:%M:%S"), msg)
    print(line, flush=True)
    with open(LOG, "a") as f:
        f.write(line + "\n")


def send(method, path, token=None):
    req = urllib.request.Request(BASE + path, method=method)
    if token is not None:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read().decode("utf-8", "replace")


class Api:
    def __init__(self):
        self.token = None

    def issue_token(self):
        _, data = self.call("POST", "/token", auth=False)
        stats["tokens"] += 1
        log("token #%d issued" % stats["tokens"])
        return data["token"]

    def call(self, method, path, auth=True):
        """Return (status, data): data is parsed JSON on 200 and None on 404.

        401/403: fetch a new token and retry. 429: wait the Retry-After period and retry.
        5xx and transport errors: back off and retry. Other statuses stop the run.
        """
        transient = 0
        while True:
            if auth and self.token is None:
                self.token = self.issue_token()
            try:
                status, headers, body = send(method, path, self.token if auth else None)
            except OSError as e:  # URLError, timeouts and connection resets
                status, headers, body = "transport", None, repr(e)
            stats["http"] += 1
            stats[str(status)] += 1

            if status == 200:
                try:
                    return 200, json.loads(body)
                except ValueError:
                    status = "bad-json"
                    stats[status] += 1
            if status == 404:
                return 404, None
            if status in (401, 403):
                log("%s %s -> %s, token refused; fetching a new token" % (method, path, status))
                self.token = None
                transient += 1
            elif status == 429:
                if headers is None or headers.get("Retry-After") is None:
                    raise RuntimeError("429 with no Retry-After header: %s" % body[:300])
                wait = float(headers["Retry-After"])
                log("%s %s -> 429, waiting %.1fs as instructed" % (method, path, wait))
                time.sleep(wait + 1)
                continue
            elif status == "transport" or status == "bad-json" or status >= 500:
                transient += 1
                log("%s %s -> %s, retry %d: %s" % (method, path, status, transient, body[:200]))
                time.sleep(min(2 ** transient, 30))
            else:
                raise RuntimeError("%s %s -> %s, not retrying: %s" % (method, path, status, body[:300]))

            if transient > MAX_TRANSIENT:
                raise RuntimeError("%s %s still failing after %d tries" % (method, path, transient))


def cached(name, fetch_fn):
    path = os.path.join(DATA, name + ".json")
    if os.path.exists(path):
        with open(path) as f:
            return json.load(f)
    entry = fetch_fn()
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(entry, f)
    os.replace(tmp, path)
    return entry


def fetch(api, path):
    status, data = api.call("GET", path)
    return {"status": status, "data": data}


def fetch_orders(api):
    pages = []
    page_no = 1
    while True:
        entry = cached("orders-page-%d" % page_no, lambda: fetch(api, "/orders?page=%d" % page_no))
        if entry["status"] != 200:
            raise RuntimeError("orders page %d: status %s" % (page_no, entry["status"]))
        page = entry["data"]
        if page["page"] != page_no:
            raise RuntimeError("asked for page %d, got %r" % (page_no, page["page"]))
        pages.append(page)
        log("orders page %d of %d: %d items" % (page_no, page["total_pages"], len(page["items"])))
        if page["next"] is None:
            break
        expected = "/orders?page=%d" % (page_no + 1)
        if page["next"] != expected:
            raise RuntimeError("next link %r after page %d, expected %r" % (page["next"], page_no, expected))
        page_no += 1
    if len(pages) != pages[-1]["total_pages"]:
        raise RuntimeError("fetched %d pages but total_pages is %d" % (len(pages), pages[-1]["total_pages"]))
    return pages


def customer(api, cid, memo):
    if cid not in memo:
        safe = urllib.parse.quote(cid, safe="")
        memo[cid] = cached("customer-" + safe, lambda: fetch(api, "/customers/" + safe))
    return memo[cid]


def placed_utc(text):
    # Offsets such as +02:00 are converted to UTC before the window test.
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        raise ValueError("placed_at has no offset: %r" % text)
    return dt.astimezone(timezone.utc)


def run():
    os.makedirs(DATA, exist_ok=True)
    api = Api()
    pages = fetch_orders(api)

    seen = {}
    listings = 0
    duplicates = 0
    conflicts = []
    for page in pages:
        for item in page["items"]:
            listings += 1
            oid = item["id"]
            if oid in seen:
                duplicates += 1
                if seen[oid] != item:
                    conflicts.append(oid)
                continue
            seen[oid] = item
    log("listings %d, distinct orders %d, repeated listings discarded %d, conflicting repeats %d"
        % (listings, len(seen), duplicates, len(conflicts)))
    if conflicts:
        raise RuntimeError("repeated order ids with different content: %s" % conflicts[:10])
    log("statuses (exact strings): %s" % dict(Counter(o["status"] for o in seen.values())))

    qualifying = [o for o in seen.values()
                  if o["status"] == "shipped" and WINDOW_START <= placed_utc(o["placed_at"]) < WINDOW_END]
    log("qualifying orders: %d" % len(qualifying))

    memo = {}
    unknown = []
    total = 0
    by_region = {r: 0 for r in REGIONS}
    for o in qualifying:
        c = customer(api, o["customer_id"], memo)
        if c["status"] == 404:
            unknown.append(o["customer_id"])
            continue
        if c["status"] != 200:
            raise RuntimeError("customer %s: status %s" % (o["customer_id"], c["status"]))
        cust = c["data"]
        amount, pct, region = o["amount_cents"], cust["discount_pct"], cust["region"]
        if not (isinstance(amount, int) and amount >= 0):
            raise RuntimeError("order %s: amount_cents %r" % (o["id"], amount))
        if not (isinstance(pct, int) and 0 <= pct <= 100):
            raise RuntimeError("customer %s: discount_pct %r" % (o["customer_id"], pct))
        if region not in by_region:
            raise RuntimeError("customer %s: region %r" % (o["customer_id"], region))
        # Round half up per order, in integer cents. Cross-checked against Decimal.
        discounted = (amount * (100 - pct) + 50) // 100
        check = int((Decimal(amount) * (100 - pct) / 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))
        if discounted != check:
            raise RuntimeError("rounding mismatch on order %s: %d vs %d" % (o["id"], discounted, check))
        by_region[region] += discounted
        total += discounted

    if unknown:
        raise RuntimeError("qualifying orders with unknown customers (404): %s" % sorted(set(unknown)))
    count = len(qualifying)
    if sum(by_region.values()) != total:
        raise RuntimeError("region sum does not equal total")

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    with open(RESULT, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    log("result: %s" % json.dumps(result))
    log("http stats: %s" % dict(stats))


if __name__ == "__main__":
    run()

